function makeDappleShader() {
	const vert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec3 aNormal;
		attribute vec2 aTexCoord;

		uniform mat4 uModelViewMatrix;
		uniform mat4 uProjectionMatrix;
		uniform mat3 uNormalMatrix;

		varying vec2 vTexCoord;
		varying vec3 vNormal;
		varying vec3 vPosition;
		varying vec3 vObjPosition;
		varying vec3 vRawNormal;

		void main(void) {
			vec4 objSpacePosition = vec4(aPosition, 1.0);

			vObjPosition = objSpacePosition.xyz;
			vec4 worldSpacePosition = uModelViewMatrix * objSpacePosition;
			gl_Position = uProjectionMatrix * worldSpacePosition;
			vTexCoord = aTexCoord;
			vPosition = worldSpacePosition.xyz;
			vRawNormal = aNormal;
			vNormal = uNormalMatrix * aNormal;
		}
	`

	const frag = `
		precision highp float;
		varying vec2 vTexCoord;
		varying vec3 vRawNormal;
		varying vec3 vNormal;
		varying vec3 vPosition;
		varying vec3 vObjPosition;
		uniform sampler2D shadow;
		uniform vec2 size;
		uniform float t;
		uniform float sizeFrac;

		float rand(vec2 co) {
			return fract(sin(dot(co.xy, vec2(12.9898,78.233))) * 43758.5453);
		}

		const int samples = ${highRes ? 9 : 7 };
		void main() {
			float samplesf = float(samples);
			float light = 0.;
			float r = size.x * sizeFrac;
			for (int y = -samples; y <= samples; y++) {
				float yf = float(y);
				for (int x = -samples; x <= samples; x++) {
					float xf = float(x);
					if (xf*xf + yf*yf > samplesf*samplesf) continue;
					float off = rand(gl_FragCoord.xy*200. + vec2(xf*50., yf*10.)*dot(gl_FragCoord.xy, vec2(1.,1.)) + t);
					vec2 coord = vec2(
						(xf+off+float(samples))/float(2*samples+1),
						(yf+off+float(samples))/float(2*samples+1)
					) * vec2(r) / size + vTexCoord; 
					light += (1.-smoothstep(0.8, 1., length(vec2(xf/samplesf, yf/samplesf)))) * texture2D(shadow, coord).x;
				}
			}
			light /= (samplesf) * (samplesf) * ${Math.PI};
			light = pow(light, 0.25);
			vec4 shadow = ${glslColor('#556878')};
			vec4 mid = ${glslColor('#d4d0c1')};
			vec4 bright = ${glslColor('#ffffff')};
			if (light < 0.75) {
				gl_FragColor = mix(shadow, mid, light/0.75);
			} else {
				gl_FragColor = mix(mid, bright, (light-0.75)/0.25);
			}
		}
	`

	return [vert, frag]
}

function glslColor(colorInput) {
	const c = color(colorInput)
	return `vec4(${(red(window.color(c))/255).toFixed(2)}, ${(green(window.color(c))/255).toFixed(2)}, ${(blue(window.color(c))/255).toFixed(2)}, 1.)`
}

