let shadowBuffer
let dappleShader
let sizeFrac
const branches = []

const highRes = false
Framebuffer.forceWebGL1 = true

function setup() {
	createCanvas(600, 600, WEBGL)
	pixelDensity(1)
	shadowBuffer = createFramebuffer({
		size: { width: highRes ? 600 : 300, height: highRes ? 600 : 300 },
		antialias: true
	})
	dappleShader = createShader(...makeDappleShader())
	noiseDetail(3, 0.1)
}

function updateState() {
	sizeFrac = random(1/25, 1/10)
	let _wG_1 = 0; while ((branches.length > 0) && ++_wG_1 < 20000) {
		freeGeometry(branches.pop())
	}
	for (let i = 0; i < 5; i++) {
		branches.push(buildGeometry(`branch${i}`, (builder) => {
			const maxDepth = 6
			const addBranch = (depth) => {
				builder.push()
				const branchLength = map(depth, 0, maxDepth, 50, 25)
				builder.translate(0, -branchLength/2)
				const r = map(depth, 0, maxDepth, 5, 1)
				if (depth >= maxDepth) {
					builder.cone(r, -branchLength, 3, 1)
				} else {
					builder.cylinder(r, branchLength, 3, 1)
				}
				builder.translate(0, -branchLength/2)
				if (depth >= maxDepth) {
					builder.triangle(
						0, 0,
						-random(5, 10), -random(10, 30),
						random(5, 10), -random(10, 30)
					)
				} else {
					const numChildren = round(random(1, 3))
					for (let i = 0; i < numChildren; i++) {
						builder.push()
						builder.rotateZ(random(-1, 1) * map(depth, 0, maxDepth, 0.2, 0.4) * PI)
						builder.rotateY(random(TWO_PI))
						addBranch(depth + 1)
						builder.pop()
					}
				}
				builder.pop()
			}
			builder.scale(0.7)
			addBranch(0)
		}))
	}
}

let prevIdx = -1
function draw() {
	clear()
	background(255)
	const t = millis()

	idx = floor(t / 8000)
	if (idx !== prevIdx) {
		prevIdx = idx
		updateState()
	}

	shadowBuffer.draw(() => {
		clear()
		background(255)
		noStroke()
		fill(0)

		branches.forEach((branch, i) => {
			push()
			translate(0, 700, i * -100)
			scale(8)
			rotateZ(sin(t*0.00065+i*0.5)*PI*0.005 + noise(t*0.00065, i*20) * PI * map(sin(t/10000), -1, 1, 0.01, 0.03, true))
			model(branch)
			pop()
		})
	})

	push()
	noStroke()
	shader(dappleShader)
	dappleShader.setUniform('size', [shadowBuffer.width, shadowBuffer.height])
	dappleShader.setUniform('shadow', shadowBuffer.color)
	dappleShader.setUniform('t', t)
	dappleShader.setUniform('sizeFrac', sizeFrac)
	plane(width, -height)
	pop()
}
